import 'package:flutter/material.dart';
import 'package:hive_flutter/hive_flutter.dart';
import 'package:whohasmy/presentation/app.dart';

/// Application entry point.
/// 
/// Initializes Hive storage before running the app.
void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  
  // Initialize Hive boxes before any UI renders
  await Hive.initFlutter();
  
  // Register adapters (generated by build_runner)
  // import 'package:whohasmy/infrastructure/storage/adapters.g.dart';
  
  runApp(const WhoHasMyApp());
}
